INSERT INTO events (id, season_id, title, description, location, starts_at, archived, created_at, updated_at)
VALUES
    ('c0000001-0000-4000-8000-000000000001', 'b0000001-0000-4000-8000-000000000001', 'Cabaret de rentrée', 'Premier cabaret de la saison 2026-2027. Montage technique dès 17h30, accueil du public à 19h00. Formats courts (12 à 15 min), relances possibles entre les équipes. Buvette et restauration légère sur place.', 'Théâtre Molière, 5 place Sébastopol, 59000 Lille', '2026-09-11T17:30:00Z', FALSE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
    ('c0000002-0000-4000-8000-000000000002', 'b0000001-0000-4000-8000-000000000001', 'Match vs Bruxelles', 'Match d''impro franco-belge en deux manches. Briefing arbitres à 19h30, coup d''envoi à 20h00. Public invité à voter entre les manches — prévoir un MC dynamique et une équipe de bénévoles pour la billetterie.', 'Salle Pasteur, 12 rue Pasteur, 59000 Lille', '2026-09-25T18:00:00Z', FALSE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
    ('c0000003-0000-4000-8000-000000000003', 'b0000001-0000-4000-8000-000000000001', 'Déplacement Amiens', 'Rencontre ligue régionale à Amiens. Départ car partagé depuis Lille à 15h30 (RDV gare Lille-Flandres). Repas prévu sur place à 18h00 avant le spectacle. Retour estimé vers 23h30.', 'MJC Jules Verne, 2 rue des Otages, 80000 Amiens', '2026-10-03T16:30:00Z', FALSE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
    ('c0000004-0000-4000-8000-000000000004', 'b0000001-0000-4000-8000-000000000001', 'Format long : Science-fiction', 'Long form thématique SF sur 45 minutes. Répétition exploratoire le mardi précédent (obligatoire pour les joueuses et joueurs retenus). Ambiance sonore et lumières travaillées — DJ et régisseur lumière convoqués dès 18h30.', 'Le Spotlight, 68 rue de la Barre, 59000 Lille', '2026-10-16T18:00:00Z', FALSE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
    ('c0000005-0000-4000-8000-000000000005', 'b0000001-0000-4000-8000-000000000001', 'Cabaret Halloween', 'Spécial frissons et costumes encouragés. Décorations sur place dès 16h00. Spectacle en deux vagues (20h00 et 22h00) — indiquer votre créneau préféré dans les dispos. Contenu tout public avec quelques surprises.', 'La Halle aux Toiles, 25 rue de la Halle, 59200 Tourcoing', '2026-10-30T18:30:00Z', FALSE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
    ('c0000006-0000-4000-8000-000000000006', 'b0000001-0000-4000-8000-000000000001', 'Match vs Gand', 'Match international amical contre les Gantoises. Échauffement collectif à 19h00, match à 20h00. Équipe belge confirmée ; arbitrage bilingue FR/NL. Billetterie en ligne ouverte jusqu''au jeudi précédent.', 'Théâtre de la Gare, 185 rue Colbert, 59000 Lille', '2026-11-07T19:00:00Z', FALSE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
    ('c0000007-0000-4000-8000-000000000007', 'b0000001-0000-4000-8000-000000000001', 'Cabaret des voisins', 'Scène ouverte aux troupes locales du Nord. Chaque troupe passe 20 minutes ; Les Improbots clôture la soirée. Accueil des troupes invitées à 18h00, montage mutualisé. Pot de fin de soirée prévu.', 'Maison Folie de Wazemmes, 68 rue de Wazemmes, 59000 Lille', '2026-11-20T17:30:00Z', FALSE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
    ('c0000008-0000-4000-8000-000000000008', 'b0000001-0000-4000-8000-000000000001', 'Déplacement Paris', 'Festival hivernal parisien — créneau matinal pour enchaîner avec un atelier l''après-midi. TGV depuis Lille à 07h12 recommandé. Hébergement non pris en charge ; liste de collocations sur le canal troupe.', 'Théâtre du Marais, 37 rue Volta, 75003 Paris', '2026-12-05T09:00:00Z', FALSE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
    ('c0000009-0000-4000-8000-000000000009', 'b0000001-0000-4000-8000-000000000001', 'Cabaret de Noël', 'Impro et chants de fin d''année. Chorale invitée pour deux reprises en ouverture et clôture. Dress code rouge et vert bienvenu. Tombola au profit du fonds de roulement de la troupe.', 'La Verrière, 16 rue Gosselet, 59000 Lille', '2026-12-18T19:00:00Z', FALSE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
    ('c0000010-0000-4000-8000-000000000010', 'b0000001-0000-4000-8000-000000000001', 'Jam Impro Nouvel An', 'Format libre tous styles — propositions du public tirées au sort. Pas de fil rouge imposé ; MC facilite les transitions. Séance de 2h30 avec pause à mi-parcours. Débutants et confirmé·es sur scène.', 'Le Biplan, 81 rue de Cambrai, 59000 Lille', '2027-01-08T18:30:00Z', FALSE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
    ('c0000011-0000-4000-8000-000000000011', 'b0000001-0000-4000-8000-000000000001', 'Match vs Rouen', 'Tournoi inter-ligues en best-of-three. Chaque manche dure 25 minutes. Rouennais en déplacement — prévoir hébergement pour 4 personnes si vous pouvez loger. Diffusion en direct sur la page Facebook de la troupe.', 'Théâtre Sébastopol, 15 place Sébastopol, 59000 Lille', '2027-01-22T19:00:00Z', FALSE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
    ('c0000012-0000-4000-8000-000000000012', 'b0000001-0000-4000-8000-000000000001', 'Cabaret court format', 'Scènes courtes rythmées (8 min chrono). Chronomètre visible du public. Trois slots par demi-équipe ; changement de décor rapide. Idéal pour tester de nouveaux formats avant le gala.', 'Le Colisée, 13 rue Jean Lebas, 59100 Roubaix', '2027-01-29T19:30:00Z', FALSE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
    ('c0000013-0000-4000-8000-000000000013', 'b0000001-0000-4000-8000-000000000001', 'Déplacement Reims', 'Invité·es par la Ligue d''Improvisation de Reims. Spectacle unique en soirée ; atelier partagé l''après-midi (14h-16h) avec les Reims·oises. Covoiturage organisé via le tableur partagé.', 'Comédie de Reims, 39 rue Chanzy, 51100 Reims', '2027-02-06T17:00:00Z', FALSE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
    ('c0000014-0000-4000-8000-000000000014', 'b0000001-0000-4000-8000-000000000001', 'Duo impro musical', 'Improvisation en duo avec piano live. Répétition musicale le lundi précédent à 20h00 au local. Répertoire jazz et chanson française ; partitions fournies. Public assis, salle intimiste (120 places).', 'Le Splendid, 68 rue de la Barre, 59000 Lille', '2027-02-19T19:00:00Z', FALSE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
    ('c0000015-0000-4000-8000-000000000015', 'b0000001-0000-4000-8000-000000000001', 'Cabaret printanier', 'Thèmes imposés par le public via ardoises à l''entrée. Tirage des thèmes à 20h05 — pas de thème choisi à l''avance. Ambiance conviviale ; terrasse ouverte si météo clémente.', 'Salle Concorde, 1 avenue de la Créativité, 59650 Villeneuve-d''Ascq', '2027-03-05T19:00:00Z', FALSE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
    ('c0000016-0000-4000-8000-000000000016', 'b0000001-0000-4000-8000-000000000001', 'Match vs Namur', 'Aller du derby transfrontalier. Namurois en visite ; retour match prévu à Namur en avril. Supporters belges attendus — renforcer l''accueil et la billeterie. After au café voisin.', 'Le Nouveau Siècle, 45 boulevard des Cités Unies, 59000 Lille', '2027-03-19T19:30:00Z', FALSE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
    ('c0000017-0000-4000-8000-000000000017', 'b0000001-0000-4000-8000-000000000001', 'Déplacement Strasbourg', 'Week-end ligue Est — deux spectacles sur la journée du samedi. Nuitée en auberge de jeunesse réservée (participation 35 €). Départ vendredi 16h00, retour dimanche soir.', 'Kafteur, 18 rue de la Krutenau, 67000 Strasbourg', '2027-03-27T08:00:00Z', FALSE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
    ('c0000018-0000-4000-8000-000000000018', 'b0000001-0000-4000-8000-000000000001', 'Cabaret du printemps', 'Soirée multi-formats : match, long form court et cabaret. Trois blocs de 30 minutes avec pause unique. Programmation dévoilée le jour J — place à l''improvisation dans l''organisation aussi.', 'La Condition Publique, 14 place Faidherbe, 59100 Roubaix', '2027-04-09T17:30:00Z', FALSE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
    ('c0000019-0000-4000-8000-000000000019', 'b0000001-0000-4000-8000-000000000001', 'Long form : Polar', 'Enquête improvisée sur une soirée entière. Personnages récurrents ; le public note ses indices sur une fiche remise à l''entrée. Durée 50 minutes sans entracte — concentration maximale.', 'Le Prato, 12 rue du Prato, 59000 Lille', '2027-04-23T18:00:00Z', FALSE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
    ('c0000020-0000-4000-8000-000000000020', 'b0000001-0000-4000-8000-000000000001', 'Apérock Mai', 'Format festif mêlant impro et musique live. Apéro dès 18h30, premier slot à 19h30. Food trucks sur le parvis. En cas de pluie, report au dimanche suivant (même horaire).', 'Gare Saint-Sauveur, 74 avenue de Saint-Sauveur, 59000 Lille', '2027-05-07T17:00:00Z', FALSE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
    ('c0000021-0000-4000-8000-000000000021', 'b0000001-0000-4000-8000-000000000001', 'Braquage', 'Concept braquage improvisé : six joueuses et joueurs, un fil rouge policier, twists garantis. Répétition bloquante le mercredi (19h-21h). Masques et accessoires fournis par la troupe.', 'Le Spotlight, 68 rue de la Barre, 59000 Lille', '2027-05-15T17:30:00Z', FALSE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
    ('c0000022-0000-4000-8000-000000000022', 'b0000001-0000-4000-8000-000000000001', 'Match vs Belgique', 'Retour du derby — sélection nationale belge B. Enjeu amical mais public nombreux attendu. Diffusion possible ; éviter spoilers sur les réseaux avant 22h00. Équipement audio renforcé.', 'Théâtre de la Digue, 42 rue de la Digue, 59000 Lille', '2027-05-21T18:30:00Z', FALSE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
    ('c0000023-0000-4000-8000-000000000023', 'b0000001-0000-4000-8000-000000000001', 'Commis d''Office', 'Format cuisine / impro : quatre commis, un chef MC, régie scène pour les changements de plateau. Ingrédients mystère révélés 10 minutes avant chaque manche. Public goûte les créations en fin de show.', 'Le Grand Sud, 21 rue du Grand Sud, 59000 Lille', '2027-06-04T17:30:00Z', FALSE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
    ('c0000024-0000-4000-8000-000000000024', 'b0000001-0000-4000-8000-000000000001', 'Match vs France', 'Rencontre nationale exhibition — cadre prestigieux. Presse locale conviée ; interview possible avant le match. Tenue sombre recommandée pour la photo officielle à 19h00.', 'Opéra de Lille (salle du Nouveau Siècle), 45 boulevard des Cités Unies, 59000 Lille', '2027-06-18T18:00:00Z', FALSE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
    ('c0000025-0000-4000-8000-000000000025', 'b0000001-0000-4000-8000-000000000001', 'Déplacement Lyon', 'Invité·es au festival d''été lyonnais. Créneau en fin d''après-midi pour profiter de la ville le matin. Billets TGV groupés — contacter les orgas avant le 15 juin pour la réservation.', 'Espace Gerson, 55 rue Vauban, 69006 Lyon', '2027-07-03T14:00:00Z', FALSE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
    ('c0000026-0000-4000-8000-000000000026', 'b0000001-0000-4000-8000-000000000001', 'Cabaret d''été #1', 'Open air improvisé dans le parc. Repas partagé type picnic à 18h00 ; spectacle à 20h00 quand la lumière baisse. Prévoir tenue décontractée et anti-moustiques. Annulé si orage.', 'Parc Jean-Baptiste Lebas, entrée rue Solférino, 59000 Lille', '2027-07-10T18:00:00Z', FALSE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
    ('c0000027-0000-4000-8000-000000000027', 'b0000001-0000-4000-8000-000000000001', 'Cabaret d''été #2', 'Best-of de saison : reprises des formats qui ont marché en 2026-2027. Vote du public pour le numéro de clôture. Bar mobile sur site ; paiement CB uniquement.', 'Parc Barbieux, allée du Parc, 59100 Roubaix', '2027-07-24T17:00:00Z', FALSE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
    ('c0000028-0000-4000-8000-000000000028', 'b0000001-0000-4000-8000-000000000001', 'Gala de clôture', 'Finale de la saison — soirée habillée. Remise des trophées internes (vote troupe). Toutes les personnes disponibles sur les dispos seront convoquées au montage dès 16h00. Standing ovation encouragée.', 'Théâtre du Nord, 1 place Sébastopol, 59000 Lille', '2027-08-06T18:30:00Z', FALSE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
    ('c0000029-0000-4000-8000-000000000029', 'b0000001-0000-4000-8000-000000000001', 'Déplacement Bruxelles', 'Clôture internationale à Bruxelles. Train 15h18 depuis Lille-Europe ; arrivée à la gare du Midi. Repas belge prévu à 18h00. Retour TGV 23h12 — qui peut propose covoiturage gare.', 'Théâtre Marni, 37 rue de la Réforme, 1050 Bruxelles', '2027-08-14T15:30:00Z', FALSE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
    ('c0000030-0000-4000-8000-000000000030', 'b0000001-0000-4000-8000-000000000001', 'Cabaret de fin d''été', 'After de clôture en mode décontracté. Pas de billetterie — chapeau à l''entrée. Formats libres, scène ouverte aux membres de la troupe qui n''ont pas joué au gala. Fin vers minuit.', 'Le Splendid, 68 rue de la Barre, 59000 Lille', '2027-08-27T18:00:00Z', FALSE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
